// Offline cache for 하나마루. Generated by tools/build.py.
const CACHE = 'hanamaru-20261020101929';
const ASSETS = ["./", "./index.html", "./manifest.webmanifest", "./icon-180.png", "./icon-192.png", "./icon-512.png", "./css/app.css?v=20261020101929", "./js/data.js?v=20261020101929", "./js/config.js?v=20261020101929", "./js/app.js?v=20261020101929"];

self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(ASSETS)));
  self.skipWaiting();
});

const VENDOR = 'hanamaru-vendor-1';   // big on-demand files (Japanese dictionary): kept across app updates

self.addEventListener('activate', e => {
  e.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(k => k !== CACHE && k !== VENDOR).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});

self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const path = new URL(req.url).pathname;
  if (path.endsWith('version.json')) return;                        // always ask the network
  if (path.includes('/js/vendor/')) {                                // dictionary: cache first, in its own cache
    e.respondWith(caches.open(VENDOR).then(c => c.match(req).then(hit => hit || fetch(req).then(res => {
      if (res.ok) c.put(req, res.clone());
      return res;
    }))));
    return;
  }
  if (path.endsWith('/js/config.js')) {                              // settings file: newest first, cache for offline
    e.respondWith(fetch(req).then(res => { const copy = res.clone(); caches.open(CACHE).then(c => c.put(req, copy)); return res; })
      .catch(() => caches.match(req, { ignoreSearch: true })));
    return;
  }
  if (req.mode === 'navigate') {                                    // page: network first (never the HTTP cache), cache when offline
    e.respondWith(fetch(req.url.split('#')[0], { cache: 'no-store', credentials: 'same-origin' }).then(res => {
      const copy = res.clone(); caches.open(CACHE).then(c => c.put('./index.html', copy)); return res;
    }).catch(() => caches.match('./index.html')));
    return;
  }
  e.respondWith(caches.match(req).then(hit => hit || fetch(req).then(res => {   // versioned files: cache first
    if (res.ok || res.type === 'opaque') { const copy = res.clone(); caches.open(CACHE).then(c => c.put(req, copy)); }
    return res;
  })));
});
